import type { SessionState, WithParts } from "../state/index.js"
import type { CompressToolContext, ToolDefinition } from "./types.js"
import { commitDurableSessionState, reconcileSessionLifecycle } from "../state/index.js"
import { saveSessionState } from "../state/persistence.js"
import { loadPrompt } from "../prompts/index.js"
import { estimateTokensBatch } from "../token-utils.js"
import { collectContentInRange, collectToolIdsInRange } from "./utils.js"
import { sendCompressNotification } from "../ui/notification.js"
import { selectDeterministicCompressionSpan } from "../messages/context-map.js"
import { findActiveManagementTurn } from "../messages/compress-transform.js"
import { isIgnoredUserMessage } from "../messages/utils.js"
import { listSessionMessages } from "../sdk/client.js"
import { getPostCompressionCooldownRemaining } from "../auto-policy.js"
import { orderCompressBlocks } from "../messages/blocks.js"

const COMPRESS_TOOL_DESCRIPTION = loadPrompt("compress-tool-spec")

export interface CompressInput {
    summary: string
    topic: string
}

interface CompressionBoundary {
    history: WithParts[]
    managementTurn?: SessionState["managementTurns"][number]
}

function isVisibleUserMessage(message: WithParts): boolean {
    return (
        message.info.role === "user" &&
        message.info.sourceType !== "synthetic" &&
        !isIgnoredUserMessage(message)
    )
}

function findExecutingToolMessage(
    rawMessages: WithParts[],
    messageId: string,
    callId?: string,
): { message: WithParts; index: number } | undefined {
    const matches = rawMessages
        .map((message, index) => ({ message, index }))
        .filter(({ message }) => message.info.id === messageId)
    if (matches.length !== 1 || matches[0].message.info.role !== "assistant") return undefined

    const hasExecutingCall = matches[0].message.parts.some(
        (part) =>
            part.type === "tool" && part.tool === "compress" && (!callId || part.callID === callId),
    )
    return hasExecutingCall ? matches[0] : undefined
}

export function resolveCompressionBoundary(
    rawMessages: WithParts[],
    state: SessionState,
    toolMessageId: string,
    callId?: string,
): CompressionBoundary {
    const activeTurn = findActiveManagementTurn(state, rawMessages)
    if (activeTurn) {
        if (activeTurn.turn.source === "squash") {
            throw new Error(
                "compress cannot complete an active `/compress squash` turn. Call squash with one block range instead. Nothing was compressed.",
            )
        }
        return {
            history: rawMessages.slice(0, activeTurn.triggerIndex),
            managementTurn: activeTurn.turn,
        }
    }

    const executing = findExecutingToolMessage(rawMessages, toolMessageId, callId)
    if (!executing) {
        throw new Error(
            "compress could not identify the executing tool call in the current session. Nothing was compressed.",
        )
    }

    const parentId = executing.message.info.parentID
    if (typeof parentId !== "string" || parentId.length === 0) {
        throw new Error(
            "compress could not identify the visible user turn that owns this call. Nothing was compressed.",
        )
    }

    const parentMatches = rawMessages
        .map((message, index) => ({ message, index }))
        .filter(({ message }) => message.info.id === parentId && isVisibleUserMessage(message))
    if (parentMatches.length !== 1 || parentMatches[0].index >= executing.index) {
        throw new Error(
            "compress could not unambiguously resolve this call's visible user boundary. Nothing was compressed.",
        )
    }

    const owner = parentMatches[0]
    const matchingManagementTurn = [...state.managementTurns]
        .reverse()
        .find((turn) => !turn.completedAt && turn.triggerMessageId === parentId)
    if (matchingManagementTurn) {
        if (matchingManagementTurn.source === "squash") {
            throw new Error(
                "compress cannot complete an active `/compress squash` turn. Call squash with one block range instead. Nothing was compressed.",
            )
        }
        return {
            history: rawMessages.slice(0, owner.index),
            managementTurn: matchingManagementTurn,
        }
    }

    const interveningVisibleUser = rawMessages
        .slice(owner.index + 1, executing.index)
        .some(isVisibleUserMessage)
    if (interveningVisibleUser) {
        throw new Error(
            "compress found another visible user turn between this call and its owner. Nothing was compressed.",
        )
    }

    return { history: rawMessages.slice(0, owner.index) }
}

function buildCompressReceipt(topic: string, blockId: string, restoreDisposition: boolean): string {
    const stored = `Compression complete. Stored [${blockId}] "${topic}" durably; the fold is already in effect.`
    const finish = `${stored} Do not call compress again this turn.`
    return restoreDisposition
        ? `${finish} Automatic compression finished. Continue the original work now, unless the preserved execution steps show it was already complete or awaiting the user.`
        : finish
}

export function createCompressTool(ctx: CompressToolContext): ToolDefinition<CompressInput> {
    return {
        description: COMPRESS_TOOL_DESCRIPTION,
        args: {
            summary: {
                type: "string",
                description:
                    "Compact structured continuation handoff described by this tool's instructions",
            },
            topic: { type: "string", description: "Short block title, usually 3-5 words" },
        },
        async execute(args, toolCtx) {
            const { client, stateManager, logger } = ctx
            const sessionId = toolCtx.sessionID
            const state = stateManager.get(sessionId)

            const input = args as Partial<CompressInput>
            const summary = typeof input.summary === "string" ? input.summary.trim() : ""
            const topic = typeof input.topic === "string" ? input.topic.trim() : ""
            if (!summary) throw new Error("compress requires a non-empty summary")
            if (!topic) throw new Error("compress requires a non-empty topic")

            const outcome = await stateManager.runExclusive(sessionId, async () => {
                let rawMessages: WithParts[]
                try {
                    rawMessages = await listSessionMessages(client, sessionId)
                } catch (error) {
                    const message = error instanceof Error ? error.message : String(error)
                    throw new Error(
                        `compress could not fetch session messages: ${message}. Nothing was compressed.`,
                    )
                }
                if (rawMessages.length === 0) {
                    throw new Error(
                        "compress could not fetch any session messages. Nothing was compressed.",
                    )
                }

                await reconcileSessionLifecycle(state, sessionId, logger, rawMessages)
                if (!state.persistenceSynchronized) {
                    throw new Error(
                        "compress could not synchronize saved session state. Nothing was compressed.",
                    )
                }

                const callId = toolCtx.id ?? toolCtx.callID
                const boundary = resolveCompressionBoundary(
                    rawMessages,
                    state,
                    toolCtx.messageID,
                    callId,
                )
                if (
                    !boundary.managementTurn &&
                    getPostCompressionCooldownRemaining(state, rawMessages) > 0
                ) {
                    const remaining = getPostCompressionCooldownRemaining(state, rawMessages)
                    throw new Error(
                        `Compression succeeded recently. Nothing was compressed. Wait ${remaining} more assistant ${remaining === 1 ? "response" : "responses"}. Only the user may override this cooldown by explicitly running \`/compress manage\`.`,
                    )
                }

                const span = selectDeterministicCompressionSpan(
                    boundary.history,
                    state,
                    logger,
                    ctx.config.protectedTurns,
                )
                if (span.messages.length === 0) {
                    return { kind: "empty" as const }
                }

                const containedToolIds = collectToolIdsInRange(
                    span.messages,
                    0,
                    span.messages.length - 1,
                )
                const estimatedCompressedTokens = estimateTokensBatch(
                    collectContentInRange(span.messages, 0, span.messages.length - 1),
                    state.modelContext?.providerId,
                )

                const candidateCompressed = {
                    toolIds: new Set(state.compressed.toolIds),
                    messageIds: new Set(state.compressed.messageIds),
                }
                for (const id of containedToolIds) candidateCompressed.toolIds.add(id)
                for (const id of span.messageIds) candidateCompressed.messageIds.add(id)

                const anchorMessageId = span.messageIds[0]
                const candidateSummaries = [
                    ...state.compressSummaries,
                    {
                        anchorMessageId,
                        messageIds: span.messageIds,
                        summary,
                        topic,
                    },
                ]
                const storedBlock = orderCompressBlocks(boundary.history, candidateSummaries).find(
                    (block) => block.summary === candidateSummaries[candidateSummaries.length - 1],
                )
                if (!storedBlock) {
                    throw new Error(
                        "compress could not reconcile the new compressed block with the current transcript. Nothing was compressed.",
                    )
                }
                const completedAt = new Date().toISOString()
                const candidateManagementTurns = boundary.managementTurn
                    ? state.managementTurns.map((turn) =>
                          turn === boundary.managementTurn
                              ? {
                                    ...turn,
                                    completedAt,
                                    completedMessageId: toolCtx.messageID,
                                }
                              : turn,
                      )
                    : [...state.managementTurns]

                const candidateState: SessionState = {
                    ...state,
                    compressed: candidateCompressed,
                    compressSummaries: candidateSummaries,
                    managementTurns: candidateManagementTurns,
                    stats: {
                        compressTokenCounter: 0,
                        totalCompressTokens:
                            state.stats.totalCompressTokens + estimatedCompressedTokens,
                    },
                    compressionCooldownAfterMessageId: toolCtx.messageID,
                }
                const persisted = await saveSessionState(candidateState, logger)
                if (!persisted) {
                    throw new Error(
                        "compress could not persist compression state. Nothing was compressed.",
                    )
                }
                commitDurableSessionState(state, candidateState)

                return {
                    kind: "compressed" as const,
                    containedToolIds,
                    selectedMessageCount: span.messageIds.length,
                    visibleHistoryCount: span.messageIds.length + span.protectedMessageIds.length,
                    topic,
                    summary,
                    estimatedCompressedTokens,
                    storedBlockId: storedBlock.label,
                    continueTask: boundary.managementTurn?.source === "automatic",
                }
            })

            if (outcome.kind === "empty") {
                return "Nothing eligible to compress. The newest configured execution steps and existing blocks remain unchanged."
            }

            await sendCompressNotification(
                client,
                logger,
                ctx.config,
                state,
                sessionId,
                outcome.containedToolIds,
                outcome.selectedMessageCount,
                outcome.topic,
                outcome.summary,
                { messageIndex: 0 },
                { messageIndex: outcome.selectedMessageCount - 1 },
                outcome.visibleHistoryCount,
                outcome.estimatedCompressedTokens,
            )

            const receipt = buildCompressReceipt(
                outcome.topic,
                outcome.storedBlockId,
                outcome.continueTask,
            )
            return receipt
        },
    }
}
